package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetMemberUseCase;
import com.example.lending.application.port.in.ListActiveLoansUseCase;
import com.example.lending.application.port.in.ListActiveLoansUseCase.ListActiveLoansQuery;
import com.example.lending.application.port.in.RegisterMemberUseCase;
import com.example.lending.application.port.in.RegisterMemberUseCase.RegisterMemberCommand;
import com.example.lending.domain.Member;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.UUID;

@RestController
@RequestMapping("/members")
public class MemberController {

    private final RegisterMemberUseCase registerMemberUseCase;
    private final GetMemberUseCase getMemberUseCase;
    private final ListActiveLoansUseCase listActiveLoansUseCase;

    public MemberController(RegisterMemberUseCase registerMemberUseCase, GetMemberUseCase getMemberUseCase,
                            ListActiveLoansUseCase listActiveLoansUseCase) {
        this.registerMemberUseCase = registerMemberUseCase;
        this.getMemberUseCase = getMemberUseCase;
        this.listActiveLoansUseCase = listActiveLoansUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public MemberResponse registerMember(@RequestBody RegisterMemberRequest request) {
        Member member = registerMemberUseCase.registerMember(new RegisterMemberCommand(request.name()));
        return MemberResponse.from(member);
    }

    @GetMapping("/{memberId}")
    public MemberResponse getMember(@PathVariable UUID memberId) {
        return MemberResponse.from(getMemberUseCase.getMember(memberId));
    }

    @GetMapping("/{memberId}/loans")
    public ActiveLoanPageResponse listActiveLoans(@PathVariable UUID memberId,
                                                  @RequestParam(defaultValue = "0") int page,
                                                  @RequestParam(defaultValue = "20") int size) {
        return ActiveLoanPageResponse.from(
                listActiveLoansUseCase.listActiveLoans(new ListActiveLoansQuery(memberId, page, size)));
    }
}

package com.example.lending.adapter.in.web;

import com.example.lending.domain.BookAlreadyOnLoanException;
import com.example.lending.domain.BookDiscardedException;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.CannotDiscardBookOnLoanException;
import com.example.lending.domain.LoanAlreadyReturnedException;
import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.LoanNotFoundException;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<ErrorResponse> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(CannotDiscardBookOnLoanException.class)
    public ResponseEntity<ErrorResponse> handleCannotDiscardOnLoan(CannotDiscardBookOnLoanException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("BOOK_ON_LOAN"));
    }

    @ExceptionHandler(BookDiscardedException.class)
    public ResponseEntity<ErrorResponse> handleBookDiscarded(BookDiscardedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("BOOK_DISCARDED"));
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    public ResponseEntity<ErrorResponse> handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}

